    sys.stderr.write('JOB_COUNT must be a non-negative integer\n')
    sys.exit(2)

run_id = '%d-%d' % (int(time.time()), os.getpid())
children = {}

for number in range(job_count):
    pid = os.fork()
    if pid == 0:
        time.sleep(0.1)
        os._exit(0 if number % 2 == 0 else 3)
    children[pid] = number

results_fd = os.open(results_path, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0644)
try:
    while children:
        try:
            pid, status = os.wait()
        except OSError, error:
            if error.errno == errno.EINTR:
                continue
            raise

        number = children.pop(pid, None)
        if number is None:
            continue

        if os.WIFEXITED(status):
            exit_status = os.WEXITSTATUS(status)
        elif os.WIFSIGNALED(status):
            exit_status = 128 + os.WTERMSIG(status)
        else:
            continue

        line = '%s,%d,%d\n' % (run_id, number, exit_status)
        while line:
            written = os.write(results_fd, line)
            line = line[written:]
finally:
    os.close(results_fd)
PYEOF
